"""
Task 012 — Parse a date string

Interprets the spec as: handle a wide variety of common date formats
and return (year, month, day) as integers. Raise ValueError if unparseable.

Key design decisions:
- Use a fixed English month-name mapping (not locale-dependent strptime %B/%b)
  so that "March 15, 2024" works on any locale.
- Prefer MM/DD/YYYY over DD/MM/YYYY for ambiguous numeric formats (US convention,
  consistent with "March 15, 2024" where month comes first).
- Avoid dateutil fallback to prevent false-positive parses for incomplete input.
"""

import re
from datetime import datetime

# Fixed English month name mappings (locale-independent)
_MONTH_NAMES = {
    'january': 1, 'february': 2, 'march': 3, 'april': 4,
    'may': 5, 'june': 6, 'july': 7, 'august': 8,
    'september': 9, 'october': 10, 'november': 11, 'december': 12,
}
_MONTH_ABBREVS = {
    'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4,
    'may': 5, 'jun': 6, 'jul': 7, 'aug': 8,
    'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12,
}
_ALL_MONTHS = {**_MONTH_NAMES, **_MONTH_ABBREVS}


def _month_num(s: str) -> int | None:
    """Convert a month name (full or abbreviated) to its integer, or None."""
    return _ALL_MONTHS.get(s.lower().rstrip('.'))


def _valid_date(year: int, month: int, day: int) -> tuple[int, int, int]:
    """Validate and return (year, month, day), raising ValueError if invalid."""
    datetime(year, month, day)  # raises ValueError for invalid dates
    return (year, month, day)


def parse_date(s: str) -> tuple[int, int, int]:
    """Parse a date string and return (year, month, day).

    Supports many common formats. For ambiguous purely-numeric formats,
    assumes US convention (month before day) when both interpretations
    would be valid.

    Raises ValueError for input that cannot be parsed as a date.
    """
    if not isinstance(s, str):
        raise ValueError(f"Expected a string, got {type(s)}")

    s = s.strip()
    if not s:
        raise ValueError("Empty string cannot be parsed as a date")

    # Normalize whitespace
    s_norm = re.sub(r'[ \t]+', ' ', s)

    # ------------------------------------------------------------------ #
    # Pattern 1: ISO / numeric with separators
    # Matches: YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD
    # ------------------------------------------------------------------ #
    m = re.fullmatch(r'(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})', s_norm)
    if m:
        year, month, day = int(m.group(1)), int(m.group(2)), int(m.group(3))
        try:
            return _valid_date(year, month, day)
        except ValueError:
            pass

    # ------------------------------------------------------------------ #
    # Pattern 2: MM/DD/YYYY or MM-DD-YYYY or MM.DD.YYYY (US style, month first)
    # ------------------------------------------------------------------ #
    m = re.fullmatch(r'(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})', s_norm)
    if m:
        a, b, year = int(m.group(1)), int(m.group(2)), int(m.group(3))
        # Try MM/DD/YYYY first (US convention)
        try:
            return _valid_date(year, a, b)
        except ValueError:
            pass
        # Fall back to DD/MM/YYYY
        try:
            return _valid_date(year, b, a)
        except ValueError:
            pass

    # ------------------------------------------------------------------ #
    # Pattern 3: 8-digit compact: YYYYMMDD
    # ------------------------------------------------------------------ #
    m = re.fullmatch(r'(\d{4})(\d{2})(\d{2})', s_norm)
    if m:
        year, month, day = int(m.group(1)), int(m.group(2)), int(m.group(3))
        try:
            return _valid_date(year, month, day)
        except ValueError:
            pass

    # ------------------------------------------------------------------ #
    # Pattern 4: Month-name formats
    # Handles: "March 15, 2024", "15 March 2024", "Mar 15, 2024",
    #          "15-Mar-2024", "2024 March 15", etc.
    # ------------------------------------------------------------------ #
    # Tokenize: split on spaces and commas and hyphens (but keep tokens)
    tokens = re.split(r'[\s,\-]+', s_norm)
    tokens = [t for t in tokens if t]  # remove empty strings

    if len(tokens) == 3:
        t0, t1, t2 = tokens

        # Case A: "Month Day Year" — e.g. "March 15, 2024" or "Mar 15 2024"
        month_a = _month_num(t0)
        if month_a and re.fullmatch(r'\d{1,2}', t1) and re.fullmatch(r'\d{4}', t2):
            try:
                return _valid_date(int(t2), month_a, int(t1))
            except ValueError:
                pass

        # Case B: "Day Month Year" — e.g. "15 March 2024" or "15 Mar 2024"
        month_b = _month_num(t1)
        if re.fullmatch(r'\d{1,2}', t0) and month_b and re.fullmatch(r'\d{4}', t2):
            try:
                return _valid_date(int(t2), month_b, int(t0))
            except ValueError:
                pass

        # Case C: "Year Month Day" — e.g. "2024 March 15"
        month_c = _month_num(t1)
        if re.fullmatch(r'\d{4}', t0) and month_c and re.fullmatch(r'\d{1,2}', t2):
            try:
                return _valid_date(int(t0), month_c, int(t2))
            except ValueError:
                pass

        # Case D: "Day Year Month" or other unusual orderings — try all combos
        # Already covered by cases above for the most common ones.
        # Try "Month Year Day" — e.g. "March 2024 15"
        month_d = _month_num(t0)
        if month_d and re.fullmatch(r'\d{4}', t1) and re.fullmatch(r'\d{1,2}', t2):
            try:
                return _valid_date(int(t1), month_d, int(t2))
            except ValueError:
                pass

    raise ValueError(f"Cannot parse {s!r} as a date")
